      "bookTitle": "Discourse on Dependent Origination",
      "author": "Mahasi Sayadaw",
      "category": "Spirituality",
      "type": "actionable",
      "headline": "Watch the Death of a Thought",
      "body": "We spend all our time waiting for thoughts to begin, but the magic lies in watching them vanish. When an anxious thought hits, do not push it away. Stare right at it and track the exact second it evaporates into thin air.",
