      "author": "Mahasi Sayadaw",
      "category": "Spirituality",
      "type": "concept",
      "headline": "Karma Is Just Neural Muscle Memory",
      "body": "Forget cosmic balance sheets. Volitional formations are mental habits you carve every time you react with greed or frustration. Each knee-jerk reaction deepens the trench, making it twice as easy to react the same way tomorrow.",
